# Fix CRMView
sed -i 's/const permissions = user?.permissions?.\[.\{1,10\}\];//g' src/views/CRMView.tsx
sed -i 's/const isReadonly = permissions?.readonly === true || user?.role === .viewer. || (user?.roles?.includes(.viewer.) && !user?.roles?.includes(.admin.) && !user?.roles?.includes(.manager.));//g' src/views/CRMView.tsx
