sed -i 's/const canDelete = user?.roles?.includes(.admin.) || (permissions ? (permissions.delete !== false && !isReadonly) : !isReadonly);/const canDelete = hasFullAccess || (!isReadonly \&\& userRoles.some((role: string) => { const p = user.permissions?.[role]; return p ? p.delete !== false : true; }));/g' src/views/CRMView.tsx

